\section{A brief review of stabilizer resource theory and non-stabilizer measures \label{app:stabreview}}
We will review the basics of stabilizer resource theory \cite{gottesman1997stabilizer, gottesman2016surviving, veitch2014resource}, by highlighting the concepts that will be necessary for our work. We will review the relevant results citing the corresponding original references, with proofs presented when they add to the discussion. A stabilizer group $\mathcal S \subseteq \mathcal P_n$ is an abelian subgroup of the Pauli group $\mathcal  P_n$ with $-1 \notin \mathcal S$. We always denote $\psi^\mathcal S$ as:
\begin{equation}
    \psi^\mathcal S \equiv \frac{1}{2^n}\sum_{s \in \mathcal S}s \in \mathcal S(\mathcal H)\;.
\end{equation}
It defines a stabilizer \emph{code}, defined as:
\begin{equation}
    V_\mathcal S \equiv\{\ket{\psi} \in \mathcal H\;|\; s\ket{\psi} = +\ket{\psi}\;,\;\forall s \in \mathcal S\}\;.
\end{equation}
Its dimension can be read by its encoding rate, defined as $k=\log_2 \mathrm{dim}V_\mathcal S =n-\mathrm{rank}(\mathcal S)$. Note that if it is full rank, $\mathrm{rank}(\mathcal S)= n$, it stabilizes a single pure state $\psi^\mathcal S= \ket{\psi^\mathcal S}\bra{\psi^\mathcal S}$. There are three sets of ``stabilizer states'':
\begin{defn}
    Let $n$ be the number of qubits. We define the set of:
    \begin{align}
         &\mathrm{stab}_n \equiv \{\psi^\mathcal S \;|\; \mathcal S\subseteq \mathcal P_n \;\mathrm{stabilizer}\;\&\;\mathrm{rank}(\mathcal S)=n\}\;,\\
        &\tilde{\mathrm{stab}}_n \equiv \{\psi^\mathcal S\;|\;\mathcal S\subseteq \mathcal P_n \;\mathrm{stabilizer}\}\;,\\
        &\mathrm{STAB}_n \equiv \mathrm{conv}(\mathrm{stab}_n)=\{\sum_{\mathcal S \in\mathrm{stab}_n}p_\mathcal S \psi^\mathcal S\;|\; p_\mathcal S \geq 0\;,\; \sum_{\mathcal S \in \mathrm{stab}_n}p_\mathcal S=1\}\;,
    \end{align}
    note the hierarchy $\mathrm{stab}_n \subseteq \tilde{\mathrm{stab}}_n \subseteq \mathrm{STAB}_n$, which is strict for $n>1$. We will refer to $\mathrm{stab}_n$ as both the set of pure stabilizer states and (full rank) stabilizer groups, and $\mathrm{STAB}_n$ as the stabilizer polytope.
\end{defn}
Note that all three sets are Clifford invariant, meaning that if a state $\psi$ is a member of any of the three sets, so does $C\psi C^\dagger$ for any Clifford unitary $C$. With that, we define:
\begin{defn}
    Let $\mathcal C \ell_n $ denote the set of $n$ qubit Clifford unitaries. Given $\mathcal F \in \{\mathrm{stab}_n, \tilde{\mathrm{stab}}_n, \mathrm{STAB}_n\}$, we define the corresponding stabilizer resource theory as the tuple $(\mathcal F, \mathcal C \ell_n)$. We say that a function of quantum states $f:\mathcal S(\mathcal H) \to \mathbb R_{\geq 0}$ is a stabilizer monotone if $f(C\psi C^\dagger)\leq f(\psi)$ for all states $\psi$ and Cliffords $C \in \mathcal C \ell_n$ and is furthermore faithful if $f(\psi) =0 \Leftrightarrow \psi \in \mathcal F$.
\end{defn}

The three different sets corresponds to three different possible free state sets in the resource theory. We will not need to be concerned with the full mixed stabilizer state resource theory, described by $\mathrm{STAB}_n$: We will be mostly concerned with the cases related to $\mathrm{stab}_n, \tilde{\mathrm{stab}}_n$. Here is a Proposition that organizes all the properties of the monotones of interest to us:
\begin{prop}
(\cite{leone2022stabilizer, leone2024stabilizer, beverland2020lower}) Let $\psi$ be a $n$ qubit quantum state. Define the following measures:
\begin{equation}
    M_\alpha(\psi) \equiv \frac{\log\left[\frac{1}{2^n}\sum_{P \in \mathcal P_n}\tr(P\psi)^{2\alpha}\right]}{1-\alpha} \quad , \quad \tilde M_2(\psi)\equiv M_2(\psi)-S_2(\psi) \quad , \quad \nu(\psi) \equiv n-\mathrm{rank}[\mathrm{Stab}(\psi)]\;,
\end{equation}
where we take $\alpha \in [0,\infty)$ and we defined $\mathrm{Stab}(\psi) \equiv \{P \in \mathcal P_n\;|\;|\mathrm{tr}(P\psi)|=1\}$. We will refer to $f \in \{M_\alpha, \tilde M_2, \nu\}$ when denoting a property valid for all three measures. The following properties hold:
\begin{enumerate}
    \item \textbf{Faithfulness: }All of them are positive-semidefinite, and are bounded above by $\leq n$, satisfying: (i) $M_\alpha(\psi) =0 \;\mathrm{or}\;\nu(\psi) = 0 \Leftrightarrow \psi \in \mathrm{stab}_n$, (ii) $\tilde M_\alpha(\psi) =0 \Leftrightarrow \psi \in \tilde{\mathrm{stab}}_n$;
    \item \textbf{Monotonicity: }All measures are Clifford-invariant, $f(C\psi C^\dagger) = f(\psi)$ for all Clifford unitaries $C$;
    \item They are additive: For any other $m$ qubit state $\sigma$, $f(\psi\otimes \sigma ) = f(\psi) + f(\sigma)$;
    \item The Rényi entropies forms an hierarchy, $M_\alpha(\psi) < M_{\alpha^\prime}(\psi)$ for any $\psi$ if $\alpha > \alpha^\prime$. Furthermore, for pure states, $M_\alpha(\psi)\leq \nu(\psi)$.
    \item The SRE lower bounds the $T$ gate count of pure states: If $t(\psi)$ is the minimum number of $T$ gates to prepare $\psi = \ket{\psi}\bra{\psi}$ from a stabilizer state, $M_\alpha(\psi)\leq t(\psi)$. 
\end{enumerate}
\label{prop:properties_monotomes}
\end{prop}
Some further properties are listed in the Supplemental Material of \cite{gu2024pseudomagic}. Notice that the definition of $\tilde M_2$ is such to construct a faithful measure for the $\tilde{\mathrm{stab}}_n$ resource theory. It captures subsystem non-stabilizerness, as it is easily shown:
\begin{prop}
    Let $\psi^\mathcal S  \in \tilde{\mathrm{stab}}_n$ and $A \subseteq [n]$. Then, 
    \begin{equation}
        \psi_A^\mathcal S = \tr_{\bar A}\psi^\mathcal S =\frac{1}{2^{|A|}}\sum_{s_A\in \mathcal S_A}s_A \in \tilde{\mathrm{stab}}_n\;,
    \end{equation}
    with $\mathcal S_A$ as defined on part 1 of Lemma \ref{lem:stabarealaw}.
    \label{prop:reducedstab}
\end{prop}
\begin{proof}
    Note that:
    \begin{align}
        \psi^\mathcal S_A &= \frac{1}{2^n}\sum_{s\in \mathcal S}\tr_{\bar A}(s) = \frac{1}{2^{|A|}}\sum_{s\in \mathcal S_A}s_A\;,
    \end{align}
    where on the second equality we have used the fact that if $\tr_{\bar A}s\neq 0$, it must be of the form $s =s_{A}\otimes \mathbb I_{\bar A}$, since otherwise the trace vanishes. Membership in $\tilde{\mathrm{stab}}_n$ is immediate by its definition.
\end{proof}
\noindent Hence, $\tilde M_2(\psi_A) >0$ witness $\psi_A\notin \tilde{\mathrm{stab}}_n$, by property 1 of Proposition \ref{prop:properties_monotomes}. It measures how far a subsystem is from coming from a stabilizer state.

\subsection{The structure of fixed nullity states \label{app:structurenullity}}

Since the nullity counts the number of Paulis fixed by a stabilizer group, we expect that given a $n$ qubit quantum state:
\begin{equation}
    \psi = \frac{1}{2^n}
    \sum_{P \in \mathcal P_n} \langle P\rangle_\psi P
\end{equation}
to have its Pauli representation constrained by its nullity. Indeed, this is the result shown in previous works, for pure states:
\begin{lem}
(\cite{leone2024learning,gu2024magic})
    Let $\psi = \ket{\psi}\bra{\psi}$ be $n$ qubit pure quantum state with nullity $\nu(\psi) =\nu$. Then, it admits the following presentation:
    \begin{equation}
        \psi= K\cdot \Pi\;,
        \label{eq:fixednullity}
    \end{equation}
    where:
    \begin{align}
    K & =\frac{1}{2^\nu} \sum_{i=0}^k \tr(h_i\psi) h_i, \\
    \Pi & =\frac{1}{|\operatorname{Stab}(\psi)|} \sum_{P \in \operatorname{Stab}(\psi)} P,
    \end{align}
    with $\Pi$ being the projector into $\mathrm{Stab}(\psi)$ and the set $\{h_i\}_{i=0}^k$ is referred as the set of bad generators, which are Paulis such that $\mathrm{supp}(\psi)\equiv \{P \in\mathcal P_n\;|\;\tr(h_i \psi)\neq 0\}$ splits into left cosets of the stabilizer group, 
    \begin{equation}
        \mathrm{supp}(\psi)  = \bigsqcup_{i=0}^k h_i \mathrm{Stab}(\psi)=\bigsqcup_{i=0}^k \{h_i s \;|\; s \in \mathrm{Stab}(\psi)\}\;,
        \label{eq:cosetdecomp}
    \end{equation}
    with $h_0=\mathbb I$. Furthermore, $[K, \Pi] =0$, $k+1 \leq 4^\nu$ and $\|K\|\leq 2^\nu$.
    \label{lem:fixednullity}
\end{lem}
This Lemma shows how the knowledge of the stabilizer group $\mathrm{Stab}(\psi)$ is a strong constraint on its Pauli support: It reduces the need of tomographic information of $\psi$ to determining $O(4^\nu)$ amplitudes in $K$.

Now, we can construct a classical representation of the quantum state. To do so, it is convenient to take a representation of Pauli operators in terms of bitstrings, dubbed what is called the symplectic representation of Pauli operators \cite{gottesman1997stabilizer, gottesman1998heisenberg}, where given $P \in \mathcal P_n$, we can write it as:
\begin{equation}
    P = \lambda X^\mathbf a Z^\mathbf b\;,
    \label{eq:symppauli}
\end{equation}
where $\lambda \in \{\pm 1, \pm i\}$ and $\mathbf a, \mathbf b \in \mathbb F_2^n$ are binary vectors, where we are using the shorthand $Q^\mathbf \equiv Q^{x_1}\otimes Q^{x_2}\otimes \cdots \otimes Q^{x_n}$. Note that storing $P \mapsto \{\lambda, \mathbf a,\mathbf b\}$ takes $O(n)$ bits, and Pauli multiplication, that takes $P_1 \in \mathcal P_n \mapsto \{\lambda_1, \mathbf a_1,\mathbf b_1\}$ and $P_2\in \mathcal P_n\mapsto \{\lambda_2, \mathbf a_2,\mathbf b_2\}$ and computes the representation of $P_1\cdot P_2 \mapsto \{\lambda_1\lambda_2 (-1)^{\mathbf b_1 \cdot \mathbf a_2}, \mathbf a_1 +\mathbf a_2, \mathbf b_1 +\mathbf b_2\}$, takes $O(n)$ time, and thus checking commutativity of two Pauli strings. Given $P \in \mathcal P_n$, denote $\mathrm S(P) = (\mathbf a , \mathbf b)^T\in \mathbb F_2^{2n}$ as its binary vector on the corresponding symplectic representation. 

There is a very nice linear-algebraic characterization of stabilizer groups in this language that will be useful later:
\begin{prop}
    Let $\mathcal S\subseteq \mathcal P_n$ be a stabilizer group, and denote $\mathrm{gen}(\mathcal S) = \{g_1, g_2, \cdots, g_{\mathrm{rank}(\mathcal S)}\}$ as a minimal generating set. We define its stabilizer tableau $\mathcal T_\mathcal S$ as:
    \begin{equation}
        \mathcal T_\mathcal S = \begin{pmatrix}
            \mathrm S(g_1) \\
            \mathrm S(g_3)\\
            \vdots\\
            \mathrm S(g_{\mathrm{rank}(\mathcal S)})
        \end{pmatrix}
        \in \mathbb F_2^{\mathrm{rank}(\mathcal S)\times 2n}
    \end{equation}
    Then:
    \begin{equation}
        s \in \mathcal S \Rightarrow \mathrm S(s) \in \mathrm{rowspace}(\mathcal T_\mathcal S) \quad \& \quad \mathbf v\in \mathrm{rowspace}(\mathcal T_\mathcal S) \Rightarrow \exists s \in \mathcal S: \mathrm S(s) =\mathbf v\;.
    \end{equation}
    \label{prop:stabmembership}
\end{prop}
\begin{proof}
 If $s\in \mathcal S$, then it exists a $\mathbf c \in \mathbb F_2^{\mathrm{rank}(\mathcal S)}$ such that:
    \begin{equation}
        s = \prod_{j=1}^{\mathrm{rank}(\mathcal S)}g_j ^{c_j}\Rightarrow \mathrm S(s) = \sum_{j=1}^{\mathrm{rank}(\mathcal S)}c_j \mathrm S(g_j)\in \mathrm{rowspace}(\mathcal T_\mathcal S)\;.
    \end{equation}
    The proof for the other statement follows similarly: Consider $\mathbf v=\sum_j c^\prime_j \mathrm S(g_j) \in \mathrm{rowspace}(\mathcal T_\mathcal S)$. Then, $s\equiv \prod_j g_j^{c^\prime_j}\in \mathcal S$, since it is a product of generators.
\end{proof}

We can use the symplectic form of Pauli strings to construct the desired representation of $\psi$ guaranteed by Lemma \ref{lem:fixednullity}. As illustrated by Proposition \ref{prop:stabmembership}, a way to encode the stabilizer group is to specify its generators, given by $\mathcal T_{\mathrm{Stab}(\psi)}$. Since the projector $\Pi$ is specified by its generators:
\begin{equation}
    \Pi = \prod_{j=1}^{\mathrm{rank}(\mathcal S)}\left(\frac{1+ g_j}{2}\right) = \frac{1}{|\mathrm{Stab}(\psi)|}\sum_{P \in \mathrm{Stab}(\psi)}P\;,
\end{equation}
knowledge of the tableau is a valid compression of the projector. Since the bad generators can be represented by $h_i \mapsto (\tr(h_i \psi),\mathrm S(h_i) )$, the final representation is given as:
\begin{equation}
    \psi  = |\psi\rangle \langle \psi|\rightsquigarrow (\mathcal T_{\mathrm{Stab}(\psi)},\{\tr(h_i\psi), \mathrm S(h_i)\}_{i=1}^k )\;,
    \label{eq:fixednullity_repfull}
\end{equation}
