\subsection{The three channel bounds}\label{sec:three}
For \emph{thermal loss}, use
\begin{equation}
 \cF^{\rm loss}_{\eta,\nu}(N)=\cF_{\eta,(1-\eta)\nu}(N).
 \label{eq:loss-bound}
\end{equation}
For $0<\nu<\eta/(1-\eta)$, its infinite-energy limit is~\cite{PLOB}
\begin{equation}
 \Phi^{\rm loss}_{\eta,\nu}
 =-\log_2(1-\eta)-\nu\log_2\eta-g(\nu).
 \label{eq:loss-plob}
\end{equation}
For $\nu\ge\eta/(1-\eta)$ all four capacities vanish.

For a \emph{noisy amplifier}, the added photon number contains both the
vacuum contribution and the thermal contribution:
\begin{equation}
 \cF^{\rm amp}_{\kappa,\nu}(N)
 =\cF_{\kappa,(\kappa-1)(\nu+1)}(N),\qquad\nu>0.
 \label{eq:amp-bound}
\end{equation}
Thus $y=\kappa N+(\kappa-1)(\nu+1)$ in Eq.~\eqref{eq:rateparams}.
For $0<\nu<1/(\kappa-1)$, the limit is~\cite{PLOB}
\begin{equation}
 \Phi^{\rm amp}_{\kappa,\nu}
 =(\nu+1)\log_2\kappa-\log_2(\kappa-1)-g(\nu).
 \label{eq:amp-plob}
\end{equation}
For $\nu\ge1/(\kappa-1)$ all four capacities vanish.

For \emph{additive noise}, set $\tau=1$ and $v=\xi$. For $0<\xi<1$,
Eq.~\eqref{eq:F} can be written without the smaller-root variable:
\begin{equation}
 u_\xi=\frac{\sqrt{(1+\xi)^2+4\xi N}-(1+\xi)}2,
 \label{eq:add-u}
\end{equation}
\begin{equation}
 \begin{aligned}
 \cF^{\rm add}_\xi(N)={}&\varphi(N-u_\xi)
       +\varphi(N+u_\xi+\xi+1)\\
 &-\varphi(N)-\varphi(N+\xi)\\
 &-g(u_\xi)-g(u_\xi+\xi).
 \end{aligned}
 \label{eq:add-bound}
\end{equation}
Its infinite-energy limit is~\cite{PLOB}
\begin{equation}
 \Phi^{\rm add}_\xi=-\log_2\xi+(\xi-1)\log_2e.
 \label{eq:add-plob}
\end{equation}
For $\xi\ge1$ all four capacities vanish. 
In each non-entanglement-breaking
case, monotonicity gives $\cF(N)\le\Phi$ at finite energy. The three
large-energy expansions are proved in Appendix~\ref{app:highenergy}; the
additive-noise case has a distinct square-root scaling of both
symplectic photon numbers.

\subsection{Entanglement accounting and finite errors}\label{sec:finite}
Let $\ER$ denote relative entropy of entanglement and $\ERi$ its
regularization. The channel-dependent quantity in Eq.~\eqref{eq:F} is the
asymptotic entanglement per mode of the exact sector resource. It also
equals $\ERi(\omega_N)$, where $\omega_N$ is obtained by transmitting one
arm of a two-mode squeezed vacuum of mean photon number $N$.

For an arbitrary correlated input $\rho_{XAY}$ of finite input REE and
transmitted mean $x$, with output $\omega_{XBY}$, the central bound is
\begin{equation}
 \ERi(X:BY)_\omega
 \le\ERi(XA:Y)_\rho+\cF_{\tau,v}(x).
 \label{eq:gain-main}
\end{equation}
It yields, for the final retained state $\zeta_n$ of an adaptive protocol,
\begin{equation}
 \ERi(\zeta_n)\le\sum_{i=1}^n\cF_{\tau,v}(x_i)
                   \le n\cF_{\tau,v}(N).
 \label{eq:adaptive}
\end{equation}
For a key protocol the retained state includes the local shields supplied
by the input-preserving reduction of
Ref.~\cite[Appendix D 3]{LossAmplifier}.

\begin{corollary}[Finite-error rate bounds]\label{cor:finite}
An $n$-use protocol with target size $d$ satisfies
\begin{align}
 (1-\varepsilon)\log_2d
 &\le\sum_i\cF_{\tau,v}(x_i)+h_2(\varepsilon),
 \label{eq:quantum-error}\\
 (1-e)^2\log_2d
 &\le\sum_i\cF_{\tau,v}(x_i)+h_2(2e-e^2),
 \label{eq:key-bound}
\end{align}
for quantum entanglement infidelity $\varepsilon$ and operational key
error $e$, respectively. Here $h_2$ is binary entropy, and each resource
sum is at most $n\cF_{\tau,v}(N)$.
\end{corollary}

Appendix~\ref{app:converse} establishes Eq.~\eqref{eq:gain-main} before
proving concavity and applying it to the successive adaptive inputs.
The replica limit concerns independent copies of a fixed state; it imposes
no independence assumption on successive channel uses. Vanishing error
in Eqs.~\eqref{eq:quantum-error}--\eqref{eq:key-bound} proves
Theorem~\ref{thm:gaussian}.

\subsection{Achievable benchmarks and comparisons}\label{sec:comparison}
The Gaussian output $\omega_N$ has entropies $S(R)=g(N)$,
$S(B)=g(y)$, and $S(RB)=g(u)+g(w)$. Hashing in the better communication
direction achieves~\cite{DevetakWinter,PGPBL,RCI}
\begin{equation}
 R_{\rm hash}(N)=
 \big[\max\{g(N),g(y)\}-g(u)-g(w)\big]_+,
 \label{eq:hashing}
\end{equation}
where $[z]_+=\max\{z,0\}$. The larger marginal is always Bob's for the
noisy amplifier and additive-noise channel. Consequently,
\begin{equation}
 R_{\rm hash}(N)\le Q_2=D_2\le P_2=K_2\le\cF_{\tau,v}(N).
 \label{eq:bracket}
\end{equation}
This is an explicit achievable benchmark, without an assertion that
hashing is optimal among available distillation protocols.

We evaluate the balanced Gaussian squashing constructions of
Refs.~\cite{DSW,Goodenough}, denoted $U_{\rm DSW}$ and $U_{\rm GEW}$, and
compare with
\begin{equation}
 U_{\rm prev}(N)=\min\{U_{\rm DSW}(N),U_{\rm GEW}(N),\Phi\}.
 \label{eq:previous}
\end{equation}
Figure~\ref{fig:bounds} displays all three channel families.
Table~\ref{tab:comparison} gives the values at $N=1$: the relative
reductions from $U_{\rm prev}$ are $34.91\%$, $40.86\%$, and $31.02\%$
for the stated thermal-loss, noisy-amplifier, and additive-noise examples. (Appendix~\ref{app:numerics}
specifies the covariance-matrix evaluation used for both the table and figure.)

